export type ThemeChoice = "system" | "light" | "dark";
export const THEME_KEY = "oa-theme";

/** Runs inline in <head> before first paint, so a stored choice never flashes the other theme. */
export const THEME_BOOT = `try{var t=localStorage.getItem("${THEME_KEY}");if(t==="light"||t==="dark")document.documentElement.dataset.theme=t}catch(e){}`;

export function readTheme(): ThemeChoice {
  try {
    const t = localStorage.getItem(THEME_KEY);
    return t === "light" || t === "dark" ? t : "system";
  } catch { return "system"; }
}

export function applyTheme(t: ThemeChoice) {
  const root = document.documentElement;
  try {
    if (t === "system") { localStorage.removeItem(THEME_KEY); delete root.dataset.theme; }
    else { localStorage.setItem(THEME_KEY, t); root.dataset.theme = t; }
  } catch { if (t === "system") delete root.dataset.theme; else root.dataset.theme = t; }
}
"use client";
import { useEffect, useState } from "react";
import { applyTheme, readTheme, type ThemeChoice } from "@/lib/theme";
import { MoonIcon, SunIcon, SystemIcon } from "@/components/icons";
import { cn } from "@/lib/utils";

const OPTIONS: { value: ThemeChoice; label: string; Icon: typeof SunIcon }[] = [
  { value: "system", label: "System theme", Icon: SystemIcon },
  { value: "light", label: "Light theme", Icon: SunIcon },
  { value: "dark", label: "Dark theme", Icon: MoonIcon },
];

/** Three-state theme switch (system / light / dark), stored in localStorage. `tone="shell"` for the navy header. */
export function ThemeToggle({ tone = "surface", className }: { tone?: "surface" | "shell"; className?: string }) {
  const [theme, setTheme] = useState<ThemeChoice>("system");
  useEffect(() => setTheme(readTheme()), []);
  function choose(t: ThemeChoice) { applyTheme(t); setTheme(t); }
  return (
    <div role="group" aria-label="Colour theme" className={cn("inline-flex items-center", className)}>
      {OPTIONS.map(({ value, label, Icon }) => {
        const on = theme === value;
        return (
          <button key={value} type="button" aria-pressed={on} aria-label={label} title={label}
            onClick={() => choose(value)}
            className={cn("inline-flex size-11 items-center justify-center rounded-md transition-colors duration-150",
              tone === "shell"
                ? on ? "bg-white/15 text-shell-ink" : "text-shell-ink-2 hover:bg-white/10 hover:text-shell-ink"
                : on ? "bg-rail text-ink" : "text-ink-2 hover:bg-ink/5 hover:text-ink")}>
            <Icon size={18} />
          </button>
        );
      })}
    </div>
  );
}
import type { Metadata, Viewport } from "next";
import localFont from "next/font/local";
import { THEME_BOOT } from "@/lib/theme";
import "./globals.css";

// Public Sans from the repo (src/fonts): builds offline, no request to Google at build or run time.
const publicSans = localFont({
  src: "../fonts/PublicSans-Variable.woff2", weight: "100 900", style: "normal",
  variable: "--font-public-sans", display: "swap",
});

export const metadata: Metadata = { title: "Ocean Above", description: "Book flights in plain language" };
export const viewport: Viewport = {
  width: "device-width", initialScale: 1,
  themeColor: [{ media: "(prefers-color-scheme: light)", color: "#0e2f4a" }, { media: "(prefers-color-scheme: dark)", color: "#0a2236" }],
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={publicSans.variable} suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: THEME_BOOT }} />
      </head>
      <body>{children}</body>
    </html>
  );
}
import Link from "next/link";

/** Small footer with the legal links (login page and legal pages). */
export function SiteFooter({ className = "" }: { className?: string }) {
  return (
    <footer className={`flex flex-wrap items-center justify-center gap-x-2 px-4 py-3 text-sm text-ink-2 ${className}`}>
      <Link href="/privacy" className="inline-flex min-h-11 items-center px-2 underline-offset-4 hover:text-ink hover:underline">Privacy Policy</Link>
      <span aria-hidden>·</span>
      <Link href="/terms" className="inline-flex min-h-11 items-center px-2 underline-offset-4 hover:text-ink hover:underline">Terms of Service</Link>
    </footer>
  );
}
import fs from "node:fs";
import path from "node:path";
import Link from "next/link";
import { Fragment, type ReactNode } from "react";
import { legalSection } from "@/lib/legal";
import { parseInline, type Inline } from "@/lib/markdown";
import { ThemeToggle } from "@/components/theme-toggle";
import { SiteFooter } from "@/components/site-footer";

/** Inline markdown from our own legal text: **bold**, *italic* / _italic_ (whole-line, e.g. "Last updated"). */
function inline(nodes: Inline[]): ReactNode {
  return nodes.map((n, i) => {
    switch (n.t) {
      case "text": return <Fragment key={i}>{n.v}</Fragment>;
      case "br": return <br key={i} />;
      case "b": return <strong key={i} className="font-semibold">{inline(n.c)}</strong>;
      case "i": return <em key={i}>{inline(n.c)}</em>;
      case "code": return <code key={i}>{n.v}</code>;
      case "a": return <a key={i} href={n.href} className="text-primary underline">{inline(n.c)}</a>;
    }
  });
}
const text = (s: string) => inline(parseInline(/^_(.+)_$/.test(s) ? `*${s.slice(1, -1)}*` : s));

/** Read at build time (the page is static); src/content/legal.md mirrors the coordinator's legal.md. */
function load(title: string) {
  const md = fs.readFileSync(path.join(process.cwd(), "src/content/legal.md"), "utf8");
  return legalSection(md, title);
}

export function LegalPage({ title }: { title: "Privacy Policy" | "Terms of Service" }) {
  const s = load(title);
  return (
    <div className="flex min-h-dvh flex-col">
      <header className="flex h-14 shrink-0 items-center justify-between bg-shell px-4 text-shell-ink" data-shell>
        <Link href="/" className="inline-flex min-h-11 items-center text-base font-bold tracking-[-0.01em]">Ocean Above</Link>
        <ThemeToggle tone="shell" />
      </header>
      <main className="mx-auto w-full max-w-2xl flex-1 px-4 py-8 sm:py-12">
        <article className="space-y-3 text-[15px] leading-relaxed text-ink [&_ul]:list-disc [&_ul]:space-y-1.5 [&_ul]:pl-5">
          <h1 className="mb-4 text-2xl font-bold tracking-[-0.01em]">{s.title}</h1>
          {s.blocks.map((b, i) => b.t === "p"
            ? <p key={i} className={/^_.+_$/.test(b.text) ? "text-sm text-ink-2" : undefined}>{text(b.text)}</p>
            : <ul key={i}>{b.items.map((it, j) => <li key={j}>{text(it)}</li>)}</ul>)}
        </article>
      </main>
      <SiteFooter />
    </div>
  );
}
