@import "tailwindcss";

/* Direction A "Timetable" (docs/iterations/04-web/D1/design-proposal.md). Two themes: light (default) and dark.
   Theme = system unless <html data-theme="light|dark"> is set (components/theme-toggle.tsx). */
:root {
  --ground: #f3f5f7;      /* page */
  --surface: #ffffff;     /* cards, composer */
  --rail: #e9edf1;        /* conversation list, skeletons */
  --ink: #102030;         /* text, strong rules: 16.5:1 on surface */
  --ink-2: #4a5866;       /* secondary text: 7.3:1 on surface */
  --placeholder: #5e6b78; /* 5.5:1 */
  --hairline: #cbd3db;    /* 1px dividers (decorative) */
  --field: #8794a1;       /* input borders: 3.1:1 */
  --shell: #0e2f4a;       /* header band */
  --shell-ink: #ffffff;   /* 13.8:1 */
  --shell-ink-2: #b7c9d9; /* 8.1:1 */
  --accent: #0b5d8f;      /* primary action, focus, links, service line */
  --accent-hover: #094b74;
  --accent-ink: #ffffff;  /* text on accent: 7.1:1 */
  --accent-tint: #dde8f2; /* user message, selection: ink 13.3:1 */
  --ok: #1a6b34;    --ok-bg: #e6f4ea;     /* 5.8:1 */
  --warn: #7a4a00;  --warn-bg: #fff1d6;   /* 6.7:1 */
  --danger: #b42318; --danger-bg: #fdecea; /* 5.8:1 */
  --scrim: rgb(16 32 48 / 0.4);
  --overlay-shadow: 8px 0 24px rgb(16 32 48 / 0.18);
  color-scheme: light;
  --ease-out: cubic-bezier(0.2, 0, 0, 1);
  --dur-1: 150ms; /* hover, colour */
  --dur-2: 200ms; /* enter, drawer */
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
  --ground: #0c1721;
  --surface: #15232f;
  --rail: #101d29;
  --ink: #e6edf3;         /* 13.5:1 on surface, 15.3:1 on ground */
