  --accent: #4ba3db;      /* 5.8:1 on surface */
  --accent-hover: #6db6e6;
  --accent-ink: #06131d;  /* text on accent: 6.8:1 */
  --accent-tint: #1d3a52; /* ink on it 10.0:1 */
  --ok: #6fd08c;    --ok-bg: #12301e;     /* 7.6:1 */
  --warn: #f2b84b;  --warn-bg: #3a2a0a;   /* 7.7:1 */
  --danger: #ff8a7a; --danger-bg: #3d1714; /* 6.9:1 */
  --scrim: rgb(0 0 0 / 0.55);
  --overlay-shadow: 8px 0 24px rgb(0 0 0 / 0.5);
  color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --ground: #0c1721;
